/* Check the SQL half of lib/error-help.ts against errors real SQLite produces.
 *
 * Same reasoning as scripts/test-error-help.mjs: a rule written against the
 * message you *remember* passes its own test and does nothing in production.
 * SQLite's wording is specific ("no such column", "misuse of aggregate") and
 * differs from MySQL and Postgres, so every case here is generated by running a
 * broken query through the same sql.js build the student's browser loads.
 *
 * Usage: npm run test:sql-help
 */
import initSqlJs from "sql.js";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { explainSqlError } from "../lib/error-help.ts";

const SETUP = `
CREATE TABLE employees (id INTEGER, name TEXT, city TEXT, salary INTEGER);
CREATE TABLE departments (id INTEGER, name TEXT);
INSERT INTO employees VALUES (1, 'Priya', 'Delhi', 50000);
INSERT INTO departments VALUES (1, 'Data');
`;

// [ label, a query that must fail, the lesson slug we expect to point at ]
const CASES = [
  ["unquoted text", "SELECT * FROM employees WHERE city = Delhi", "sql-where"],
  ["misspelled column", "SELECT salery FROM employees", "sql-where"],
  ["missing table", "SELECT * FROM staff", "sql-intro"],
  ["ambiguous column", "SELECT name FROM employees JOIN departments ON employees.id = departments.id", "sql-joins"],
  ["aggregate in WHERE", "SELECT city FROM employees WHERE COUNT(*) > 1 GROUP BY city", "sql-groupby"],
  // NOT concat(): SQLite grew that in 3.44, so it works here. NOW() is the
  // MySQL habit that genuinely has no SQLite equivalent, which is the mistake
  // this rule exists to catch.
  ["unknown function", "SELECT NOW() FROM employees", "sql-intro"],
  ["keyword out of order", "SELECT * WHERE id = 1 FROM employees", "sql-intro"],
  ["missing comma", "SELECT name city FROM employees WHERE", "sql-intro"],
  ["unclosed bracket", "SELECT COUNT(* FROM employees", "sql-intro"],
];

const wasm = await readFile(path.join(process.cwd(), "public", "sqljs", "sql-wasm.wasm"));
const SQL = await initSqlJs({ wasmBinary: wasm });
const db = new SQL.Database();
db.run(SETUP);

let pass = 0;
const fails = [];

for (const [label, query, expectedLesson] of CASES) {
  let raw = "";
  try {
    db.exec(query);
    fails.push(`${label}: the query did NOT fail — the test case is wrong, not the rule`);
    continue;
  } catch (e) {
    raw = String(e?.message ?? e);
  }

  const help = explainSqlError(raw);
  if (!help) {
    fails.push(`${label}: no rule matched\n        sqlite said: ${raw}`);
    continue;
  }
  if (help.lesson !== expectedLesson) {
    fails.push(`${label}: matched but pointed at "${help.lesson}", expected "${expectedLesson}"\n        sqlite said: ${raw}\n        title: ${help.title}`);
    continue;
  }
  pass++;
  console.log(`  ok   ${label.padEnd(22)} → ${help.title}`);
}

db.close();   // without this, libuv asserts on teardown when the process exits

console.log("");
for (const f of fails) console.log(` FAIL  ${f}`);
console.log(`\n${pass}/${CASES.length} real SQLite errors explained.`);
if (fails.length) process.exit(1);
